var i=`system-design-trade-offs`;var o=101;var n={en:[{id:`T101-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`System Design Trade-offs`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Brooks's Law warns that adding people to a late software project may make it later because onboarding and communication cost time.`},{id:`B`,text:`System design is the deliberate choice among imperfect alternatives under explicit requirements.`},{id:`C`,text:`The Theory of Constraints holds that overall throughput is limited by a small number of bottlenecks.`},{id:`D`,text:`The Pareto principle is a heuristic that a minority of causes often account for a majority of outcomes.`}]},{id:`T101-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`System Design Trade-offs`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Identify the current constraint, exploit it efficiently, subordinate upstream work to its capacity, elevate capacity when justified and repeat as bottlenecks move.`},{id:`B`,text:`Estimate coordination paths, module separability and onboarding capacity before scaling a team.`},{id:`C`,text:`Compare required customization, vendor reliability, security/compliance, integration effort, exit costs, data ownership and long-term support.`},{id:`D`,text:`Start with workload, constraints, invariants and failure tolerance.`}]},{id:`T101-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`A team choosing a modular monolith over microservices may accept a shared deployment in exchange for simpler transactions and lower operations cost.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`Validate against severity, not just frequency.`},{id:`B`,text:`It can define growth signals for reconsideration.`},{id:`C`,text:`A hotel platform may build its unique reservation workflows but buy transactional email delivery and payment processing, where infrastructure and compliance are costly.`},{id:`D`,text:`Increasing upload workers only grows the queue; parallelizing or optimizing OCR may improve completion throughput.`}]},{id:`T101-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`System Design Trade-offs`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Avoid 'best practice' answers without context.`},{id:`B`,text:`Benefits such as developer happiness or lower risk are real but hard to monetize; document them explicitly.`},{id:`C`,text:`Little's Law does not predict tail latency or fix overload.`},{id:`D`,text:`Conway's Law is a tendency, not a deterministic theorem.`}]},{id:`T101-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`Good architecture optimizes a portfolio of properties such as correctness, delivery speed, reliability, cost and adaptability.`}]}]},{id:`T101-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`An architecture choice has one objectively best answer independent of context.`}]}]},{id:`T101-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Architectural options have second-order effects on hiring, debugging, testing and incident response; optimize for the actual organization.`}]}]},{id:`T101-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`System Design Trade-offs`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Start with workload, constraints, invariants and failure tolerance.`},{id:`B`,text:`Improving any non-bottleneck stage always increases end-to-end throughput.`},{id:`C`,text:`Trade-offs disappear if a team chooses the most popular technology.`},{id:`D`,text:`System design is the deliberate choice among imperfect alternatives under explicit requirements.`}]},{id:`T101-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`System Design Trade-offs`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`An architecture choice has one objectively best answer independent of context.`},{id:`B`,text:`Architectural options have second-order effects on hiring, debugging, testing and incident response; optimize for the actual organization.`},{id:`C`,text:`It can define growth signals for reconsideration.`},{id:`D`,text:`Onboarding and coordination have zero impact on delivery throughput.`}]},{id:`T101-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A team choosing a modular monolith over microservices may accept a shared deployment in exchange for simpler transactions and lower operations cost.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to calculate and validate queue metrics from production-like traces, detect unstable load and propose a capacity threshold with alerts.`},{id:`B`,text:`Ask an agent to map team ownership onto a proposed modular architecture, identify dependency bottlenecks and suggest one minimal organizational change.`},{id:`C`,text:`Ask an agent to estimate three automation options using low, base and high scenarios, including operating costs and a break-even point.`},{id:`D`,text:`Ask an agent to compare two architectures for a booking service with a weighted decision matrix, failure scenarios, assumptions and an ADR-style recommendation.`}]},{id:`T101-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Which nonfunctional requirement would reverse your current architectural decision?`}]}]},{id:`T101-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A team choosing a modular monolith over microservices may accept a shared deployment in exchange for simpler transactions and lower operations cost.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`System Design Trade-offs`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T101-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A team choosing a modular monolith over microservices may accept a shared deployment in exchange for simpler transactions and lower operations cost.`,b:!0},{t:` — propose three checks for `},{t:`System Design Trade-offs`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T101-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A team choosing a modular monolith over microservices may accept a shared deployment in exchange for simpler transactions and lower operations cost.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T101-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`System Design Trade-offs`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A team choosing a modular monolith over microservices may accept a shared deployment in exchange for simpler transactions and lower operations cost.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T101-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Компроміси системного проєктування`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Закон Брукса попереджає, що додавання людей до запізнілого проєкту може ще більше затримати його через навчання та комунікацію.`},{id:`B`,text:`Системне проєктування — свідомий вибір між недосконалими альтернативами за конкретних вимог.`},{id:`C`,text:`Теорія обмежень стверджує, що загальну пропускну здатність обмежує невелика кількість вузьких місць.`},{id:`D`,text:`Принцип Парето — евристика, за якою невелика частина причин часто створює більшість результатів.`}]},{id:`T101-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Компроміси системного проєктування`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Визначте обмеження, використайте його ефективно, узгодьте роботу інших ділянок із його потужністю, збільште потужність за потреби та повторіть цикл.`},{id:`B`,text:`Перш ніж збільшувати команду, оцініть канали координації, незалежність модулів і можливість онбордингу.`},{id:`C`,text:`Порівнюйте кастомізацію, надійність постачальника, безпеку й вимоги, інтеграцію, вартість виходу, власність на дані та підтримку.`},{id:`D`,text:`Починайте з навантаження, обмежень, інваріантів і допустимих відмов.`}]},{id:`T101-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Команда може обрати модульний моноліт замість мікросервісів, погодившись на спільний реліз заради простіших транзакцій і менших витрат.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Але враховуйте тяжкість, а не лише частоту.`},{id:`B`,text:`При цьому зафіксувати сигнали для перегляду рішення.`},{id:`C`,text:`Готельна платформа може сама створювати унікальні сценарії бронювання, але купувати доставку транзакційних листів і платіжний процесинг, де інфраструктура й відповідність вимогам дорогі.`},{id:`D`,text:`Додавання upload-воркерів лише збільшує чергу; оптимізація OCR може підвищити загальну пропускну здатність.`}]},{id:`T101-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Компроміси системного проєктування`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Уникайте «найкращих практик» без контексту.`},{id:`B`,text:`Переваги на кшталт задоволення команди чи зниження ризику реальні, хоча їх важко оцінити грошима; фіксуйте їх.`},{id:`C`,text:`Закон Літтла не передбачає хвостові затримки й не усуває перевантаження.`},{id:`D`,text:`Закон Конвея — тенденція, а не безумовна теорема.`}]},{id:`T101-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Добра архітектура балансує коректність, швидкість розробки, надійність, вартість і гнучкість.`}]}]},{id:`T101-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Архітектурне рішення має одну об’єктивно найкращу відповідь незалежно від контексту.`}]}]},{id:`T101-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Архітектура впливає на найм, дебаг, тести й реакцію на інциденти; оптимізуйте для реальної команди.`}]}]},{id:`T101-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Компроміси системного проєктування`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Починайте з навантаження, обмежень, інваріантів і допустимих відмов.`},{id:`B`,text:`Прискорення будь-якого етапу, що не є вузьким місцем, завжди збільшує пропускну здатність.`},{id:`C`,text:`Компроміси зникають, якщо команда вибрала найпопулярнішу технологію.`},{id:`D`,text:`Системне проєктування — свідомий вибір між недосконалими альтернативами за конкретних вимог.`}]},{id:`T101-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Компроміси системного проєктування`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Архітектурне рішення має одну об’єктивно найкращу відповідь незалежно від контексту.`},{id:`B`,text:`Архітектура впливає на найм, дебаг, тести й реакцію на інциденти; оптимізуйте для реальної команди.`},{id:`C`,text:`При цьому зафіксувати сигнали для перегляду рішення.`},{id:`D`,text:`Онбординг і координація ніяк не впливають на швидкість розробки.`}]},{id:`T101-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Команда може обрати модульний моноліт замість мікросервісів, погодившись на спільний реліз заради простіших транзакцій і менших витрат.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента розрахувати й перевірити метрики черги з реалістичних traces, виявити нестабільне навантаження та запропонувати поріг потужності й alerts.`},{id:`B`,text:`Попросіть агента накласти власність команд на модульну архітектуру, знайти вузькі місця залежностей і запропонувати одну мінімальну організаційну зміну.`},{id:`C`,text:`Попросіть агента оцінити три способи автоматизації за песимістичним, базовим та оптимістичним сценаріями з експлуатаційними витратами й точкою окупності.`},{id:`D`,text:`Попросіть агента порівняти дві архітектури бронювання через матрицю критеріїв, сценарії збоїв, припущення й рішення у форматі ADR.`}]},{id:`T101-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Яка нефункціональна вимога змусить переглянути ваше архітектурне рішення?`}]}]},{id:`T101-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Команда може обрати модульний моноліт замість мікросервісів, погодившись на спільний реліз заради простіших транзакцій і менших витрат.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Компроміси системного проєктування`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T101-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Команда може обрати модульний моноліт замість мікросервісів, погодившись на спільний реліз заради простіших транзакцій і менших витрат.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Компроміси системного проєктування`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T101-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Команда може обрати модульний моноліт замість мікросервісів, погодившись на спільний реліз заради простіших транзакцій і менших витрат.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T101-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Компроміси системного проєктування`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Команда може обрати модульний моноліт замість мікросервісів, погодившись на спільний реліз заради простіших транзакцій і менших витрат.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var a={slug:i,topicId:101,questions:n};export{a as default,n as questions,i as slug,o as topicId};